M = [
{"id":"adakkurbaneti","yol":["Yeminler","Yemin"],"baslik":"Adak kurbanının eti","ar":"لحم الأضحية المنذورة",
 "hanefi":"Adak (nezir) kurbanının etinin tamamı fakirlere dağıtılır; adayan kişi, onun usulü (anne, baba, dede, nine), fürûu (çocuk, torun) ve eşi bu etten yiyemez, zengin olanlara da verilmez. Yerlerse yedikleri miktarın değerini fakirlere tasadduk etmeleri gerekir. Adak kurbanının kesim vakti, belirli bir gün adanmamışsa bayram günleriyle sınırlı değildir.",
 "mez":{"maliki":["Sahibi yiyebilir (bazı türlerde)","Genel adakta yenebileceğini söyleyenler vardır."],
        "safii":["Sahibi yiyemez","Hepsi tasadduk edilir."],
        "hanbeli":["Sahibi yiyemez","Hepsi fakirlere verilir."]},
 "sebep":"Adak kurbanının vacip bir sadaka mı, yoksa vacip kurban (udhiye) hükmünde mi olduğu.",
 "delil":[["ayet","Hac 22:29","./#22-29","“…Adaklarını yerine getirsinler…”"],
          ["ayet","İnsan 76:7","./#76-7","“Onlar adaklarını yerine getirirler…”"]],
 "usul":"Adak, kişinin kendisine vacip kıldığı bir sadakadır; sadaka da sahibine ve nafakası ona ait olanlara verilmez."},
{"id":"kulhakki","yol":T,"baslik":"Kul hakkı ve helalleşme","ar":"حقوق العباد والتحلل منها",
 "hanefi":"Allah’a karşı işlenen günahlar samimi tövbe ile affedilir; kul hakkı ise ancak hak sahibine hakkı ödenerek ya da helallik alınarak düşer. Gasp edilen veya haksız alınan mal sahibine iade edilir; sahibi ölmüşse mirasçılarına, bulunamıyorsa sahibi adına tasadduk edilir. Gıybet ve iftira gibi manevi haklarda helallik istenir; bunun yeni bir kırgınlığa yol açacağından korkulursa kişi için dua ve istiğfar edilir, iyilikle anılır.",
 "mez":{"maliki":["Aynı","Hak sahibine ulaşılamazsa tasadduk edilir."],
        "safii":["Aynı","Tövbenin şartlarından biri hakkın iadesidir."],
        "hanbeli":["Aynı","Gıybette helallik istemenin fitneye yol açacağı durumda dua yeterlidir."]},
 "sebep":"Mezheplerde ittifak vardır; ayrılık gıybette helalleşmenin şekli konusundadır.",
 "delil":[["hadis","“Kimin kardeşine karşı bir zulmü varsa bugün helalleşsin…”",hadis("من كانت له مظلمة لأخيه من عرضه أو شيء فليتحلله منه اليوم"),"Buhârî, Mezâlim, 10."],
          ["hadis","Müflis kimdir?",hadis("أتدرون ما المفلس"),"Müslim, Birr, 59."]],
 "usul":"Kul haklarının bina edildiği esas, darlık ve ihtiyaçtır (müşâhha); Allah’ın hakları ise affa dayanır (müsâmaha)."},
{"id":"yalanruhsat","yol":T,"baslik":"Yalanın ruhsat verildiği durumlar","ar":"ما يرخص فيه من الكذب",
 "hanefi":"Yalan büyük günahtır. Hadiste yalnız üç durumda ruhsat verilmiştir: Küs iki kişiyi barıştırmak, savaşta düşmanı yanıltmak ve eşlerin aralarındaki sevgiyi artırmak için söylenen sözler. Âlimlerin çoğu bu ruhsatı mümkün olduğunca açık yalan yerine iki anlama gelebilen sözlerle (tariz) kullanmayı tavsiye eder. Şaka yollu da olsa yalan söylemek, insanları güldürmek için uydurmak ve çocuğa yalan vaat etmek caiz değildir.",
 "mez":{"maliki":["Üç durumla sınırlı","Tariz tercih edilir."],
        "safii":["Üç durumla sınırlı","Meşru bir amaca başka yolla ulaşılamıyorsa caizdir."],
        "hanbeli":["Üç durumla sınırlı","Tariz tercih edilir."]},
 "sebep":"Ruhsatın açık yalanı mı, yoksa tarizi mi kapsadığı.",
 "delil":[["hadis","İnsanların arasını bulan yalancı değildir",hadis("ليس الكذاب الذي يصلح بين الناس"),"Buhârî, Sulh, 2; Müslim, Birr, 101."],
          ["hadis","Çocuğa bir şey vaat edip vermemek",hadis("أما إنك لو لم تعطه شيئا كتبت عليك كذبة"),"Ebû Dâvûd, Edeb, 80."]],
 "usul":"Ruhsatlar, istisna oldukları için dar yorumlanır; zaruret kendi miktarınca takdir edilir."},
{"id":"borcmuhlet","yol":["Muâmelât","Borç ve para"],"baslik":"Borcunu ödeyemeyene mühlet vermek","ar":"إنظار المعسر",
 "hanefi":"Borcunu ödemeye gücü olmayan darda kalmış borçluya, durumu düzelinceye kadar mühlet vermek farzdır; onu sıkıştırmak ve borcuna ek ödeme istemek caiz değildir. Borcun bir kısmını veya tamamını bağışlamak ise daha faziletlidir. Gücü yettiği hâlde borcunu ödemeyen zengin ise zalimdir; alacaklı, hakkını yasal yollarla isteyebilir.",
 "mez":{"maliki":["Mühlet vacip","Darda olanın hapsi caiz değildir."],
        "safii":["Mühlet vacip","Dardalık ispat edilince takip durur."],
        "hanbeli":["Mühlet vacip","Bağış efdaldir."]},
 "sebep":"Mezheplerde ittifak vardır.",
 "delil":[["ayet","Bakara 2:280","./#2-280","“Eğer borçlu darlık içinde ise, eli genişleyinceye kadar ona mühlet verin. Bağışlamanız ise, bilirseniz sizin için daha hayırlıdır.”"],
          ["hadis","“Zenginin borcunu geciktirmesi zulümdür.”",hadis("مطل الغني ظلم"),"Buhârî, Havâlât, 1; Müslim, Müsâkāt, 33."]],
 "usul":"Kesin nas, darda kalan borçluya mühleti farz kılmıştır; borca gecikme bedeli eklemek faizdir."},
{"id":"vaadetmek","yol":T,"baslik":"Söz verip tutmamak","ar":"الوفاء بالوعد",
 "hanefi":"Verilen sözü yerine getirmek, Kur’an ve sünnetin emrettiği güzel ahlaktandır; bile bile tutmayacağı bir sözü vermek münafıklık alametidir. Hanefîlere göre tek taraflı vaadin yerine getirilmesi dinen gerekli olmakla birlikte hukuken zorlanamaz; ancak vaade bağlı olarak karşı taraf bir zarara girmişse (ticari vaatler gibi) vaadin bağlayıcı olduğu görüşü de vardır. Mazeret sebebiyle sözü tutamayan kişi karşı tarafı bilgilendirmeli ve gönlünü almalıdır.",
 "mez":{"maliki":["Sebebe bağlı vaat bağlayıcı","Karşı taraf vaat yüzünden bir işe girmişse vaat bağlayıcıdır."],
        "safii":["Diyaneten gerekli","Hukuken zorlanamaz."],
        "hanbeli":["Diyaneten gerekli","Hukuken zorlanamaz."]},
 "sebep":"Vaadin diyâneten mi, kazâen de mi bağlayıcı olduğu.",
 "delil":[["ayet","İsrâ 17:34","./#17-34","“…Verdiğiniz sözü yerine getirin; çünkü verilen söz sorumluluk gerektirir.”"],
          ["hadis","Münafığın alametleri",hadis("آية المنافق ثلاث إذا حدث كذب وإذا وعد أخلف"),"Buhârî, Îmân, 24; Müslim, Îmân, 107."]],
 "usul":"Diyânet (Allah katındaki sorumluluk) ile kazâ (mahkemede zorlanabilirlik) ayrımı."},
]
